def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        if i == n:
            # End of line
            break

        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows
                        if i < n:
                            if line[i] == ',':
                                fields.append(field)
                                i += 1
                            else:
                                # Invalid: closing quote not followed by comma or end
                                return None
                        else:
                            # End of line after closing quote
                            fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Loop ended without finding closing quote
                return None
        else:
            # Unquoted field
            field = ""
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Invalid: unquoted field contains quote
                    return None
                field += line[i]
                i += 1

            fields.append(field)
            if i < n and line[i] == ',':
                i += 1

    return fields

